#include <stdio.h>
#include <string.h>



int main(void) {
    char line[1002], best[1002] = "";
    if (!fgets(line, sizeof(line), stdin)) line[0] = '\0';
    char *word = strtok(line, " \t\r\n");
    while (word) {
        if (strlen(word) > strlen(best)) strcpy(best, word);
        word = strtok(NULL, " \t\r\n");
    }
    puts(best);
    return 0;
}
